export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"tr","term":"Piyasa değeri (market cap)","aka":["market cap","piyasa kapitalizasyonu","toplam piyasa değeri"],"short":"Piyasa değeri (market cap), bir kripto paranın güncel fiyatının dolaşımdaki arzla çarpılmasıyla bulunan toplam değerdir ve coinlerin büyüklüğünü karşılaştırmak için kullanılır.","body":[["Formül basittir: piyasa değeri = fiyat x ",["dolaşımdaki arz","circulating-supply"],". Bir coinin birim fiyatı tek başına ne kadar büyük olduğunu söylemez. 0,01 dolarlık bir token'ın piyasa değeri, 100 dolarlık bir coininkinden daha büyük olabilir."],"Veri siteleri ve borsalar coinleri genellikle piyasa değerine göre sıralar. Büyük piyasa değerli coinler genelde daha likittir ve daha az oynaktır; küçük olanlar ise daha sert hareket edebilir.",["Ancak piyasa değeri bir tahmindir, kasada duran nakit değildir. Coinlerin tamamı aynı anda bu fiyattan satılamaz; ince likiditede büyük satışlar fiyatı hızla düşürür. Ayrıca kilitli token'lar hesaba katılmadığı için ",["tam seyreltilmiş değer (FDV)","fully-diluted-valuation"]," ile birlikte okumak daha sağlıklıdır."]],"example":["A token'ı 0,05 ",["USDT","usdt"],"'den işlem görüyor ve dolaşımda 4 milyar adet var: piyasa değeri 0,05 x 4.000.000.000 = 200 milyon USDT. B coini 40 USDT ve dolaşımda 2 milyon adet var: piyasa değeri 40 x 2.000.000 = 80 milyon USDT. Birim fiyatı çok daha düşük olmasına rağmen A, B'den iki buçuk kat daha büyüktür. A'nın 1 USDT'ye çıkması piyasa değerinin 4 milyar USDT olması demektir; böyle hedefleri değerlendirirken bu çarpımı akılda tutmak gerekir."],"mistakes":["Birim fiyatı düşük olan bir token'ın kolayca 1 dolara çıkacağını varsaymak.","Piyasa değerini projenin elindeki para veya yatırılmış toplam sermaye sanmak.","Dolaşımdaki arzı küçük, kilitli arzı büyük token'larda yalnızca piyasa değerine bakıp FDV'yi görmezden gelmek."],"faq":[{"q":"Piyasa değeri nasıl hesaplanır?","a":"Güncel fiyat, dolaşımdaki coin sayısıyla çarpılır. Farklı veri siteleri dolaşımdaki arzı farklı hesaplayabildiği için küçük farklar görmek normaldir."},{"q":"Yüksek piyasa değeri iyi bir şey mi?","a":"Genellikle daha yüksek likidite ve daha düşük oynaklık anlamına gelir, ancak tek başına bir kalite göstergesi değildir. Token ekonomisi ve kullanım alanı da önemlidir."}],"title":"Piyasa değeri (market cap) nedir? Nasıl hesaplanır?","description":"Kripto parada piyasa değerinin nasıl hesaplandığını ve birim fiyat yerine neden market cap'e bakmanız gerektiğini öğrenin.","related":[["fully-diluted-valuation","Tam seyreltilmiş değer (FDV)","Tam seyreltilmiş değer (FDV), bir token'ın güncel fiyatının maksimum veya toplam arzla çarpılmasıyla bulunan değerdir ve tüm token'lar piyasaya çıktığında projenin ne kadar büyük görüneceğini gösterir."],["circulating-supply","Dolaşımdaki arz (circulating supply)","Dolaşımdaki arz, bir kripto paranın şu anda piyasada serbestçe alınıp satılabilen, kilitli veya rezervde tutulmayan coin ya da token miktarıdır."],["trading-volume","İşlem hacmi (Trading volume)","İşlem hacmi, belirli bir sürede, genellikle 24 saatte, bir varlığın ne kadarının alınıp satıldığını gösteren toplam miktardır."],["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."],["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"tr","term":"Piyasa yapıcı (Market maker)","aka":["market maker","likidite sağlayıcı","MM"],"short":"Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir.","body":["Piyasa yapıcı aynı anda piyasa fiyatının biraz altında bir alış emri, biraz üstünde de bir satış emri bekletir. İki taraf da dolarsa aradaki farkı kazanır. Bu sayede siz bir coin almak veya satmak istediğinizde karşınızda hep bir emir bulunur ve makas dar kalır.","Borsalar ve token projeleri, piyasanın sağlıklı işlemesi için profesyonel piyasa yapıcı firmalarla anlaşabilir. Bu firmalar genelde düşük veya negatif maker ücretlerinden yararlanır. Piyasa yapıcının da riski vardır: fiyat hızla tek yöne giderse elinde değer kaybeden bir envanter kalabilir.",["Merkeziyetsiz borsalarda bu rolü çoğunlukla otomatik piyasa yapıcılar (",["AMM","amm"],") ve ",["likidite","liquidity"]," havuzlarına fon yatıran kullanıcılar üstlenir. Sert hareketlerde piyasa yapıcıların emirlerini aniden çekmesi likiditenin bir anda kurumasına yol açabilir."]],"example":["Bir piyasa yapıcı ",["BTC","bitcoin"],"/",["USDT","usdt"]," paritesinde 59.990 USDT'den 0,5 BTC alış ve 60.010 USDT'den 0,5 BTC satış emri bekletiyor. İki emir de dolarsa 0,5 × 20 = 10 USDT brüt kazanç elde eder. ",["Maker ücreti","maker-taker-fees"]," yüzde 0,01 ise her taraf için yaklaşık 3 USDT, toplam yaklaşık 6 USDT komisyon öder ve net kazanç 4 USDT civarında kalır. Bu kazancın anlamlı olması için işlemin günde binlerce kez tekrarlanması gerekir."],"mistakes":["Piyasa yapıcıların fiyatı her zaman yukarı taşıyacağını düşünmek; görevleri yön belirlemek değil likidite sağlamaktır.","Yeni listelenen bir tokenın canlı emir defterinin, piyasa yapıcı anlaşması bittiğinde de aynı kalacağını sanmak.","Maker olarak limit emri vermek ile profesyonel piyasa yapıcılığı aynı şey sanmak."],"faq":[{"q":"Piyasa yapıcılar fiyatı manipüle eder mi?","a":"Meşru piyasa yapıcılığın amacı likidite sağlamaktır. Ancak sahte hacim veya fiyat yönlendirme gibi kötüye kullanım örnekleri de yaşanmıştır ve bunlar birçok ülkede yasa dışıdır."},{"q":"Bireysel yatırımcı piyasa yapıcı olabilir mi?","a":"Limit emirleriyle maker olarak likidite sağlayabilir ya da bir DEX likidite havuzuna fon yatırabilirsiniz. Profesyonel piyasa yapıcılık ise hızlı altyapı, büyük sermaye ve sıkı risk yönetimi gerektirir."}],"title":"Piyasa yapıcı (market maker) nedir? Nasıl kazanır","description":"Piyasa yapıcıların ne yaptığını, makastan nasıl kazandığını ve likiditeye etkisini örnek hesapla öğrenin.","related":[["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["bid-ask-spread","Alış-satış makası (spread)","Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir."],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"tr","term":"Risk-ödül oranı (Risk-reward ratio)","aka":["risk/ödül oranı","R:R","risk-getiri oranı"],"short":"Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır.","body":["Oran, giriş ile stop arasındaki mesafenin giriş ile hedef arasındaki mesafeyle karşılaştırılmasıyla bulunur. 1'e 3 oranı, 1 birim risk karşılığında 3 birim kazanç hedeflediğiniz anlamına gelir. Bazı platformlar bunu tersten, ödül/risk olarak gösterir; hangisini okuduğunuza dikkat edin.","Oran tek başına yeterli değildir, kazanma olasılığıyla birlikte düşünülmelidir. 1'e 3 oranlı işlemlerin yalnızca yüzde 30'unu kazansanız bile ücretler hariç uzun vadede kârda kalabilirsiniz. Öte yandan hedefi gerçekçi olmayan bir direncin ötesine koyarak oranı yapay şekilde yükseltmek kazanma olasılığını düşürür.",["Planı işlemden önce yapın ve ",["OCO emri","oco-order"]," gibi araçlarla stop ve hedefi birlikte girin. İşlem sırasında stop'u zarar yönüne kaydırmak oranı bozar."]],"example":[["ETH","ethereum"],"'yi 3.000 ",["USDT","usdt"],"'den alıyor, stop'u 2.900'e, hedefi 3.300'e koyuyorsunuz. Risk 100, olası kazanç 300 USDT'dir; oran 1'e 3'tür. On benzer işlemden üçünü kazanıp yedisini kaybettiğinizi düşünün: 3 × 300 = 900 USDT kazanç, 7 × 100 = 700 USDT kayıp. Ücretler hariç net sonuç 200 USDT kârdır. Aynı başarı oranıyla 1'e 1 oranında işlem yapsaydınız 400 USDT zararda olurdunuz."],"mistakes":["Kazanma olasılığını hesaba katmadan yalnızca yüksek oranlı işlemleri seçmek.","İşlem açıldıktan sonra stop'u uzaklaştırarak riski sessizce büyütmek.","İşlem ücretlerini ve kaymayı oran hesabına katmamak."],"faq":[{"q":"İyi bir risk-ödül oranı nedir?","a":"Pek çok işlemci en az 1'e 2 oranını hedefler, ama uygun oran stratejinizin kazanma olasılığına bağlıdır. Başarı oranı yüksek stratejiler daha düşük bir oranla da çalışabilir."},{"q":"Risk-ödül oranı nasıl hesaplanır?","a":"Giriş ile hedef arasındaki farkı, giriş ile stop arasındaki farka bölersiniz. Sonuç 3 ise oran 1'e 3'tür."}],"title":"Risk-ödül oranı nedir? Kripto işlemlerde hesaplama","description":"Risk-ödül oranının nasıl hesaplandığını, kazanma olasılığıyla ilişkisini ve sık yapılan hataları öğrenin.","related":[["position-sizing","Pozisyon büyüklüğü (Position sizing)","Pozisyon büyüklüğü, bir işleme ne kadar sermaye ayıracağınızı zarar durdur seviyenize ve kabul edebileceğiniz en yüksek kayba göre belirleme yöntemidir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["take-profit","Kâr al (take-profit) emri","Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir."],["oco-order","OCO emri (biri diğerini iptal eder)","OCO emri (one-cancels-the-other), birbirine bağlı iki emirden oluşan ve biri gerçekleştiği anda diğerinin otomatik olarak iptal edildiği bir emir türüdür; genellikle kâr al ve zarar durdur emrini birlikte koymak için kullanılır."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Ne kadar alacağınıza karar vermeden önce ne kadar kaybedebileceğinizi belirleyin"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"tr","term":"Vadeli işlem sözleşmesi (Futures contract)","aka":["vadeli kontrat","futures","vadeli işlemler"],"short":"Vadeli işlem sözleşmesi, bir varlığı sahiplenmeden fiyatı üzerine işlem yapmanızı sağlayan ve iki tarafın varlığı belirli bir fiyattan ileride alıp satmayı kabul ettiği türev sözleşmedir.","body":[["Vadeli işlemde coinin kendisini değil, fiyatına bağlı bir sözleşmeyi alıp satarsınız. Fiyatın yükseleceğini düşünüyorsanız long, düşeceğini düşünüyorsanız ",["short pozisyon","long-and-short"]," açarsınız. Kripto borsalarındaki vadeli işlemlerin çoğu nakit uzlaşmalıdır; yani vade sonunda coin teslim edilmez, kâr veya zarar hesabınıza yansıtılır."],["Kriptoda iki ana tür vardır: vadesi olmayan sürekli (",["perpetual","perpetual-futures"],") vadeli kontratlar ve belirli bir tarihte kapanan teslimatlı (çeyreklik) vadeli kontratlar. Ayrıca teminatın ",["USDT","usdt"]," ile mi yoksa coinin kendisiyle mi yatırıldığına göre USDT teminatlı ve coin teminatlı sözleşmeler bulunur."],["Vadeli işlemler kaldıraçla yapılabildiği için küçük bir teminatla büyük bir pozisyon açabilirsiniz. Bu, kazancı da kaybı da büyütür ve fiyat aleyhinize giderse pozisyonunuz likidasyona (tasfiyeye) uğrayabilir. Sözleşme büyüklüğü, ücretler ve maksimum ",["kaldıraç","leverage"]," borsaya göre değişir."]],"example":[["BTC","bitcoin"]," 60.000 USDT iken 0,1 BTC'lik bir long vadeli pozisyonu 10x kaldıraçla açıyorsunuz. Pozisyon değeri 6.000 USDT, bağladığınız teminat 600 USDT'dir. Fiyat 63.000'e çıkarsa kârınız 0,1 × 3.000 = 300 USDT olur, yani teminatınıza göre yüzde 50. Fiyat 57.000'e düşerse aynı oranda 300 USDT kaybedersiniz. Spotta aynı 600 USDT ile yalnızca 0,01 BTC alabilir ve 3.000 USDT'lik harekette 30 USDT kazanır ya da kaybederdiniz."],"mistakes":["Vadeli işlemi spot alımla aynı sanmak; vadeli pozisyonda coinin sahibi olmazsınız.","Kaldıracı kazancı büyüten bir araç olarak görüp kaybı da aynı oranda büyüttüğünü unutmak.","Sürekli ve teslimatlı kontratları karıştırıp vade tarihini veya fonlama ödemelerini gözden kaçırmak."],"faq":[{"q":"Vadeli işlem ile spot arasındaki fark nedir?","a":"Spotta coini satın alır ve sahibi olursunuz. Vadeli işlemde yalnızca fiyatına bağlı bir sözleşme tutarsınız, kaldıraç kullanabilir ve düşüşten de kazanmak için short açabilirsiniz."},{"q":"Türkiye'de kripto vadeli işlem yapılabilir mi?","a":"Kurallar ülkeden ülkeye değişir ve Türkiye'de kripto varlık hizmet sağlayıcıları SPK düzenlemesine tabidir. Hangi ürünlere erişebileceğiniz, kullandığınız platformun lisansına ve şartlarına bağlıdır."}],"title":"Vadeli işlem sözleşmesi nedir? Kripto futures rehberi","description":"Kripto vadeli işlem sözleşmesinin nasıl çalıştığını, türlerini, kaldıraç ve likidasyon riskini örnekle öğrenin.","related":[["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["delivery-futures","Teslimatlı vadeli kontrat (Delivery futures)","Teslimatlı vadeli kontrat, önceden belirlenmiş bir vade tarihinde kapanan ve o gün uzlaşma fiyatı üzerinden hesaplanan kripto vadeli işlem sözleşmesidir."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["margin-trading","Marjin ticareti (Margin trading)","Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"tr","term":"Çapraz marjin (Cross margin)","aka":["çapraz teminat","cross margin","çapraz mod"],"short":"Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur.","body":[["Çapraz modda bir pozisyon zarar ettiğinde borsa, tasfiyeyi önlemek için hesaptaki boş bakiyeyi otomatik olarak teminat olarak kullanır. Bu, ",["likidasyon","liquidation"]," fiyatını izole moda göre girişten uzaklaştırır ve geçici dalgalanmalarda pozisyonun ayakta kalmasına yardım eder."],"Bedeli şudur: tek bir kötü pozisyon tüm hesap bakiyenizi eritebilir. Pozisyon tasfiye olursa yalnızca ilk ayırdığınız teminatı değil, hesaptaki kullanılabilir bakiyenin büyük kısmını veya tamamını kaybedebilirsiniz. Bir pozisyondaki gerçekleşmemiş kâr ise diğer pozisyonlar için teminat görevi görebilir.",["Çapraz marjin, birbirini dengeleyen pozisyonlar tutan veya hesabını aktif olarak yöneten deneyimli işlemciler tarafından sıkça kullanılır. ",["Birleşik işlem hesabı","unified-trading-account"]," sunan borsalarda çapraz marjin farklı coinlerdeki bakiyeleri de teminat sayabilir; kurallar borsadan borsaya değişir."]],"example":["Vadeli hesabınızda 2.000 ",["USDT","usdt"]," var ve çapraz modda 10x kaldıraçla 5.000 USDT'lik ",["ETH","ethereum"]," long açıyorsunuz; ",["başlangıç teminatı","initial-margin"]," 500 USDT. İzole modda bu pozisyon fiyat yaklaşık yüzde 9,5 düştüğünde tasfiye olurdu. Çapraz modda ise tüm 2.000 USDT teminat sayıldığı için, ",["bakım teminatı","maintenance-margin"]," yüzde 0,5 kabul edilirse fiyatın yaklaşık yüzde 39,5 düşmesi gerekir. Ancak o noktada tasfiye olursanız kaybınız 500 değil, yaklaşık 1.975 USDT olur."],"mistakes":["Çapraz modda yalnızca pozisyon için ayırdığınız teminatı kaybedebileceğinizi sanmak.","Hesaba yeni para yatırınca bunun otomatik olarak açık pozisyonların teminatı olduğunu unutmak.","Birden fazla yüksek kaldıraçlı pozisyonu çapraz modda açıp birinin diğerlerini sürüklemesine izin vermek."],"faq":[{"q":"Çapraz marjinde tüm paramı kaybedebilir miyim?","a":"Evet, pozisyon tasfiye olursa vadeli hesaptaki kullanılabilir bakiyenin büyük kısmı veya tamamı gidebilir. Bu yüzden çapraz modda pozisyon büyüklüğünü dikkatle seçmek gerekir."},{"q":"Çapraz marjin ne zaman mantıklıdır?","a":"Birbirini hedge eden pozisyonlar tutuyorsanız veya hesabı sürekli izliyorsanız işe yarar. Tek yönlü, yüksek kaldıraçlı spekülatif işlemlerde risk çok büyür."}],"title":"Çapraz marjin (cross margin) nedir? Riskleri","description":"Çapraz marjinin nasıl çalıştığını, likidasyon fiyatına etkisini ve tüm bakiyeyi neden riske attığını öğrenin.","related":[["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["portfolio-margin","Portföy marjini (Portfolio margin)","Portföy marjini, teminat gereksinimini her pozisyon için ayrı ayrı değil, tüm portföyün toplam riskine göre hesaplayan gelişmiş bir marjin modudur."],["unified-trading-account","Birleşik işlem hesabı (UTA)","Birleşik işlem hesabı (UTA), spot, vadeli ve opsiyon gibi farklı ürünleri tek bir hesapta toplayıp tüm bakiyenizi ortak teminat olarak kullanmanıza izin veren borsa hesap yapısıdır."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Çapraz teminat: Bir kayıp diğer pozisyonlarınızı neden vurabilir?"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"tr","term":"Long ve short pozisyon","aka":["long pozisyon","short pozisyon","uzun pozisyon","kısa pozisyon","açığa satış"],"short":"Long pozisyon, fiyatın yükselmesinden kazanç sağlamak için açılan alış pozisyonudur; short pozisyon ise fiyatın düşmesinden kazanç sağlamak için açılan satış pozisyonudur.","body":["Long, en basit hâliyle bir varlığı alıp daha yüksek fiyattan satmayı hedeflemektir. Spot piyasada coin satın almak da bir long pozisyondur. Vadeli işlemlerde ise coini almadan, fiyatına bağlı bir kontratla long açarsınız.",["Short, fiyatın düşeceği beklentisiyle önce satıp sonra daha ucuza geri almayı hedefler. Kriptoda short genellikle ",["perpetual","perpetual-futures"]," vadeli kontratlarla veya marjin hesabında coin borç alarak yapılır. Long pozisyonda en fazla yatırdığınız tutarı kaybedebilirsiniz, çünkü fiyat sıfırın altına inemez; short pozisyonda ise fiyat yükselişinin teorik bir sınırı yoktur."],["Vadeli işlemlerde her long pozisyonun karşısında bir short pozisyon vardır. ",["Fonlama oranı","funding-rate"],", hangi tarafın daha kalabalık olduğuna göre long veya short tarafına maliyet yükler. Bazı borsalar aynı kontratta aynı anda long ve short tutmanıza izin veren ",["hedge","hedging"]," modu sunar."]],"example":[["ETH","ethereum"]," 2.400 ",["USDT","usdt"]," iken iki işlemci aynı kontratta karşı pozisyon açıyor: biri 5 ETH long, diğeri 5 ETH short. ETH 2.640'a çıkarsa long tarafı 5 × 240 = 1.200 USDT kazanır, short tarafı aynı tutarı kaybeder. ETH 2.160'a düşerse tam tersi olur. İki işlemci de 5x ",["kaldıraç","leverage"]," kullandıysa yüzde 10'luk bu hareket, teminatlarına göre yüzde 50 kazanç veya kayıp anlamına gelir."],"mistakes":["Short pozisyonun kaybının da long gibi yatırılan tutarla sınırlı olduğunu sanmak; kaldıraçlı short'ta hızlı yükselişler teminatı çabuk eritir.","Long ve short'u yalnızca vadeli işlem kavramı sanmak; spot alım da bir long'dur.","Fonlama oranının hangi tarafa maliyet yüklediğini kontrol etmeden uzun süre pozisyon tutmak."],"faq":[{"q":"Long ve short ne demek?","a":"Long, fiyatın yükselmesinden kazanmayı hedefleyen alış pozisyonudur. Short, fiyatın düşmesinden kazanmayı hedefleyen satış pozisyonudur."},{"q":"Spot piyasada short açılabilir mi?","a":"Klasik spot hesapta açılamaz, çünkü elinizde olmayan bir coini satamazsınız. Short için vadeli kontratlar veya coin borç alabildiğiniz marjin hesabı gerekir."}],"title":"Long ve short pozisyon nedir? Kriptoda anlamı","description":"Long ve short pozisyonun ne anlama geldiğini, nasıl açıldığını ve risklerindeki farkı örnekle öğrenin.","related":[["short-selling","Açığa satış (Short selling)","Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["long-short-ratio","Long/short oranı (Long/short ratio)","Long/short oranı, bir vadeli işlem piyasasında long pozisyon tutan hesapların veya pozisyonların short tarafına oranını gösteren bir piyasa duyarlılığı göstergesidir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"tr","term":"Açığa satış (Short selling)","aka":["short","short selling","açığa satış işlemi","shortlamak"],"short":"Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir.","body":[["Klasik açığa satışta varlığı ödünç alır, hemen satar ve daha sonra geri alıp borcu kapatırsınız. Kriptoda bu, marjin hesabında coin borç alarak yapılabilir; bu durumda borç için faiz ödersiniz. Ancak en yaygın yöntem ",["perpetual","perpetual-futures"]," vadeli kontratlarda ",["short pozisyon","long-and-short"]," açmaktır; burada ödünç alma yoktur, maliyet ",["fonlama oranı","funding-rate"]," şeklinde ortaya çıkar."],["Açığa satışın riski long pozisyondan farklıdır. Fiyat sıfıra düşebilir, yani short'un kazancı sınırlıdır; ama fiyatın ne kadar yükselebileceğinin teorik bir sınırı yoktur. Kaldıraçlı short'larda ani yükselişler hızlı likidasyona yol açar ve çok sayıda short aynı anda kapanmak zorunda kalınca ",["short squeeze","short-squeeze"]," oluşabilir."],["Açığa satış, düşüş beklentisini işlemeye ek olarak elinizdeki coinleri satmadan değer kaybına karşı korunmak (",["hedge","hedging"],") için de kullanılır. Marjin faizleri ve borç alınabilen coinler borsadan borsaya değişir."]],"example":["Marjin hesabınızda 10 SOL borç alıp 150 ",["USDT","usdt"],"'den satıyorsunuz ve 1.500 USDT elde ediyorsunuz. Borç faizi günlük yüzde 0,05 ise günde 0,005 SOL faiz birikir. On gün sonra SOL 130 USDT'ye düşerse, 10,05 SOL'ü geri almak için yaklaşık 1.306,5 USDT ödersiniz. Kârınız yaklaşık 193,5 USDT olur. SOL 170'e çıksaydı aynı geri alım 1.708,5 USDT tutar ve yaklaşık 208,5 USDT zarar ederdiniz."],"mistakes":["Short pozisyonda kaybın sınırsız olabileceğini göz ardı edip stop koymamak.","Marjin faizini veya negatif fonlamayı hesaba katmadan short'u uzun süre tutmak.","Kalabalık short pozisyonların ani bir short squeeze ile tasfiye edilebileceğini unutmak."],"faq":[{"q":"Kriptoda nasıl short açılır?","a":"En yaygın yol perpetual vadeli kontratta satış yönünde pozisyon açmaktır. Bazı borsalar marjin hesabında coin borç alıp satmanıza da izin verir."},{"q":"Açığa satış yasal mı?","a":"Açığa satış birçok piyasada yasal ve yaygın bir işlemdir. Kripto türevlerine erişim ise ülkenin düzenlemelerine ve kullandığınız platformun lisansına bağlıdır."}],"title":"Açığa satış (short selling) nedir? Kriptoda short","description":"Kriptoda açığa satışın nasıl yapıldığını, marjin ve vadeli yöntemlerini ve sınırsız kayıp riskini öğrenin.","related":[["long-and-short","Long ve short pozisyon","Long pozisyon, fiyatın yükselmesinden kazanç sağlamak için açılan alış pozisyonudur; short pozisyon ise fiyatın düşmesinden kazanç sağlamak için açılan satış pozisyonudur."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["margin-trading","Marjin ticareti (Margin trading)","Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür."],["short-squeeze","Short squeeze (Açık pozisyon sıkışması)","Short squeeze, fiyatın ani yükselişiyle short pozisyon sahiplerinin zararı kesmek için geri alım yapmak veya tasfiye edilmek zorunda kalması ve bu zorunlu alımların fiyatı daha da yukarı itmesidir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"tr","term":"Vadeli baz (Futures basis)","aka":["baz","basis","vadeli prim","baz farkı"],"short":"Vadeli baz, bir vadeli kontratın fiyatı ile dayanak varlığın spot fiyatı arasındaki farktır ve genellikle tutar veya yıllıklandırılmış yüzde olarak ifade edilir.","body":["Vadeli fiyat spotun üzerindeyse baz pozitiftir; buna contango denir. Spotun altındaysa baz negatiftir; buna backwardation denir. Kripto piyasalarında, özellikle yükseliş dönemlerinde, teslimatlı kontratlar genellikle spotun üzerinde işlem görür, çünkü kaldıraçlı long talebi yüksektir.",["Teslimatlı kontratlarda baz vade yaklaştıkça sıfıra doğru daralır ve vade günü kontrat spot fiyata yakınsar. Bu nedenle yatırımcılar bazı yıllıklandırarak karşılaştırır: üç ay sonra sona eren bir kontratta yüzde 2'lik baz, kabaca yıllık yüzde 8 civarına denk gelir. ",["Perpetual","perpetual-futures"]," kontratlarda ise baz ",["fonlama oranı","funding-rate"]," üzerinden sürekli dengelenir."],"Baz, cash-and-carry adı verilen işlemin temelidir: spot alıp aynı miktarda vadeli satarak bazı kilitlemek. Baz piyasa duyarlılığı hakkında da fikir verir; çok yüksek baz, kaldıraçlı iyimserliğin yoğunlaştığına işaret edebilir."],"example":[["BTC","bitcoin"]," spotta 60.000 ",["USDT","usdt"],", 90 gün sonra sona eren çeyreklik kontrat ise 61.200 USDT. Baz 1.200 USDT, yani spot fiyata göre yüzde 2'dir. Bunu yıllıklandırmak için 2 × 365 / 90 hesabı yapılır ve yaklaşık yüzde 8,1 bulunur. Aynı anda 1 BTC spot alıp 1 BTC çeyreklik short açarsanız, vade günü fiyat ne olursa olsun ücretler hariç yaklaşık 1.200 USDT getiri kilitlersiniz."],"mistakes":["Farklı vadelerdeki bazı yıllıklandırmadan doğrudan karşılaştırmak.","Cash-and-carry işleminde short bacağın likidasyon riskini ve teminat ihtiyacını hesaba katmamak.","Bazın vade boyunca sabit kalacağını sanmak; arada genişleyip daralabilir."],"faq":[{"q":"Contango ve backwardation nedir?","a":"Contango, vadeli fiyatın spotun üzerinde olmasıdır. Backwardation ise vadeli fiyatın spotun altında olmasıdır ve genellikle kısa vadeli satış baskısına işaret eder."},{"q":"Baz nasıl yıllıklandırılır?","a":"Bazın spot fiyata oranı, 365'in vadeye kalan gün sayısına bölümüyle çarpılır. Bu, farklı vadelerdeki kontratları karşılaştırmayı kolaylaştırır."}],"title":"Vadeli baz (futures basis) nedir? Nasıl hesaplanır","description":"Vadeli bazın ne olduğunu, contango ve backwardation farkını ve yıllıklandırma hesabını örnekle öğrenin.","related":[["delivery-futures","Teslimatlı vadeli kontrat (Delivery futures)","Teslimatlı vadeli kontrat, önceden belirlenmiş bir vade tarihinde kapanan ve o gün uzlaşma fiyatı üzerinden hesaplanan kripto vadeli işlem sözleşmesidir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["index-price","Endeks fiyatı (Index price)","Endeks fiyatı, bir varlığın birden fazla büyük spot borsadaki fiyatlarının ağırlıklı ortalamasından hesaplanan ve vadeli kontratlar için referans olarak kullanılan fiyattır."],["funding-rate-arbitrage","Fonlama oranı arbitrajı (Funding rate arbitrage)","Fonlama oranı arbitrajı, spot piyasada bir coin alıp aynı miktarda perpetual short açarak fiyat riskini nötrlediğiniz ve pozitif fonlama ödemelerini topladığınız stratejidir."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"tr","term":"Yatırma ağı (ağ seçimi)","aka":["ağ seçimi","transfer ağı","çekim ağı","network"],"short":"Yatırma ağı, bir kripto varlığı transfer ederken işlemin hangi blokzincir üzerinden gideceğini belirleyen seçimdir; gönderen ve alan tarafın aynı ağı desteklemesi gerekir.","body":[[["USDT","usdt"],", ",["USDC","usdc"]," gibi birçok token birden fazla blokzincirde çıkarılmıştır. Örneğin USDT; ",["Ethereum","ethereum"]," (ERC20), Tron (TRC20), BNB Smart Chain (BEP20), Solana ve başka ağlarda bulunur. Borsada çekim yaparken gördüğünüz \"ağ\" menüsü, token'ın hangi zincirde gönderileceğini seçmenizi ister."],["Ağlar ücret ve hız açısından farklıdır. Bir ağda ",["çekim ücreti","withdrawal-fee"]," birkaç dolar olabilirken başka bir ağda çok daha düşük olabilir; onay süreleri de değişir. Ücretler ağ yoğunluğuna ve borsanın politikasına göre değiştiği için çekim ekranındaki güncel değere bakmak gerekir."],"En kritik kural: alıcı taraf, seçtiğiniz ağı desteklemelidir. Bir varlığı karşı tarafın desteklemediği bir ağdan gönderirseniz fonlar ulaşmayabilir ve kurtarma işlemi uzun, ücretli veya imkânsız olabilir. Borsanın yatırma sayfasında listelenen ağlar, o borsanın kabul ettiği ağlardır."],"example":"A borsasından B borsasına 1.200 USDT göndermek istiyorsunuz. A borsası ERC20, TRC20 ve BEP20 seçeneklerini sunuyor. B borsasının yatırma sayfasında ise yalnızca ERC20 ve TRC20 görünüyor. Bu durumda BEP20 seçmemelisiniz. A borsasında ERC20 çekim ücreti örneğin 4 USDT, TRC20 ücreti 1 USDT ise, TRC20 seçerek B borsasına 1.199 USDT ulaştırırsınız. Adresi de B borsasının TRC20 yatırma adresinden kopyalarsınız.","mistakes":["Sadece token adına bakıp ağ menüsünü varsayılan seçenekte bırakmak.","Alıcı tarafın yatırma sayfasında listelenmeyen bir ağdan göndermek.","Ağ ücretlerini her zaman aynı sanmak; ücretler zamanla değişebilir."],"faq":[{"q":"Yanlış ağdan kripto gönderirsem ne olur?","a":"Alıcı adres o ağda da geçerliyse fonlar oraya ulaşır ama alıcı göremeyebilir. Borsalar bazen kurtarma yapar, ancak bu garanti değildir ve ücret alınabilir."},{"q":"USDT için en iyi ağ hangisi?","a":"Tek bir doğru cevap yoktur. Alıcının desteklediği ağlar arasında ücret, hız ve güvenilirliği karşılaştırıp seçmelisiniz."}],"title":"Yatırma ağı nedir? Kripto transferinde ağ seçimi","description":"Kripto transferinde ağ seçiminin ne anlama geldiğini, ERC20, TRC20, BEP20 farkını ve yanlış ağ riskini öğrenin.","related":[["wallet-address","Cüzdan adresi (wallet address)","Cüzdan adresi, bir blokzincirde kripto almak için paylaştığınız, açık anahtardan türetilen harf ve rakamlardan oluşan bir dizidir; banka hesap numarasına benzer ama ağa özgüdür."],["memo-tag","Memo / hedef etiketi (destination tag)","Memo veya hedef etiketi, bazı coinlerde borsaya yapılan bir yatırmanın hangi kullanıcıya ait olduğunu belirlemek için adresin yanında gönderilen ek koddur."],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir."],["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"tr","term":"Mempool (bekleyen işlem havuzu)","aka":["mempool","bellek havuzu","işlem havuzu"],"short":"Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır.","body":["Bir transfer gönderdiğinizde işlem önce ağdaki düğümlere (node) yayılır ve her düğümün mempool'una girer. Madenciler veya doğrulayıcılar yeni blok oluştururken buradan işlem seçer. Blok alanı sınırlı olduğu için genellikle daha yüksek ücret ödeyen işlemleri önce alırlar.",["Ağ yoğun olduğunda mempool dolar ve düşük ücretli işlemler saatlerce bekleyebilir. ",["Bitcoin","bitcoin"],"'de ücret sat/vB (sanal bayt başına ",["satoshi","satoshi"],") cinsinden ölçülür. ",["Ethereum","ethereum"],"'da ise taban ücret ve öncelik ücreti (bahşiş) vardır."],["Mempool herkese açık olduğu için bazı botlar burada bekleyen işlemleri görüp önüne geçmeye çalışabilir; bu ",["MEV","mev"]," konusuyla ilgilidir. Takılı kalan bir işlemi bazı cüzdanlarda daha yüksek ücretle yeniden göndererek hızlandırabilirsiniz (Bitcoin'de RBF, Ethereum'da aynı nonce ile yeni işlem)."]],"example":"Bitcoin ağında mempool'da 150.000 işlem beklediğini ve sonraki bloğa girmek için yaklaşık 25 sat/vB gerektiğini varsayalım. İşleminiz 200 vB büyüklüğünde ve 5 sat/vB ücretle gönderilmiş, yani 1.000 satoshi ödemişsiniz. Bu ücretle saatlerce bekleyebilirsiniz. Ücreti 30 sat/vB'ye yükseltirseniz toplam ücret 6.000 satoshi olur. 1 BTC 100.000.000 satoshi olduğuna göre bu 0,00006 BTC eder ve işleminiz büyük ihtimalle birkaç blok içinde onaylanır.","mistakes":["Ağ yoğunken en düşük ücreti seçip işlemin hemen onaylanmasını beklemek.","Mempool'da bekleyen işlemi kaybolmuş sanıp aynı tutarı tekrar göndermek.","Borsa çekimlerinde ücreti sizin değil borsanın belirlediğini unutmak."],"faq":[{"q":"İşlemim mempool'da takıldı, ne yapmalıyım?","a":"Cüzdanınız destekliyorsa ücreti artırarak işlemi hızlandırabilirsiniz. Desteklemiyorsa ağ yoğunluğu azalınca işlem genellikle onaylanır veya bir süre sonra mempool'dan düşer."},{"q":"Mempool'daki işlem iptal edilebilir mi?","a":"Doğrudan iptal butonu yoktur. Bazı cüzdanlar aynı coin'i kendi adresinize daha yüksek ücretle göndererek eski işlemi geçersiz kılmanıza izin verir."}],"title":"Mempool nedir? Bekleyen işlemler ve ağ ücreti","description":"Mempool nedir, işleminiz neden bekliyor ve ücreti artırmak onayı nasıl hızlandırır; Bitcoin örneği ve hesaplamayla öğrenin.","related":[["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."],["transaction-hash","İşlem hash'i (TxID)","İşlem hash'i (TxID), blokzincire gönderilen her işleme verilen benzersiz kimlik kodudur ve işlemin durumunu bir blok gezgininde takip etmenizi sağlar."],["mev","MEV (maksimum çıkarılabilir değer)","MEV (maksimum çıkarılabilir değer), blok üreticilerinin ve botların bir bloktaki işlemlerin sırasını belirleyerek, ekleyerek veya çıkararak elde edebildiği ek kârdır."],["block-confirmations","Blok onayı (confirmation)","Blok onayı, bir işlemin bir bloğa eklenmesinden sonra üzerine eklenen her yeni bloğu ifade eder; onay sayısı arttıkça işlemin geri alınması pratikte imkânsız hâle gelir."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Gönderildi yazıyor ama ulaşmadı. Nereye bakmalısın?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"tr","term":"KYC'siz borsa (no-KYC exchange)","aka":["no-KYC borsa","kimliksiz borsa","KYC istemeyen borsa"],"short":"KYC'siz borsa, hesap açmak ve belirli limitlere kadar işlem yapmak için kimlik doğrulaması istemeyen merkezi veya merkeziyetsiz kripto alım satım platformudur.","body":[["Bu başlık iki farklı şeyi kapsar. Birincisi merkeziyetsiz borsalardır (",["DEX","dex"],"): kendi cüzdanınızı bağlarsınız, varlıklarınız sizde kalır ve kimlik sorulmaz. İkincisi, kimlik istemeden düşük çekim limitleri sunan bazı merkezi borsalardır."],["Merkezi tarafta '",["KYC","kyc"]," yok' ifadesi genellikle sınırlıdır. Birçok platform belirli bir günlük çekim tutarına kadar kimlik istemez, şüpheli bir işlem görürse veya kurallar değişirse KYC talep eder ve o ana kadar fonlar bekleyebilir. Ayrıca bu borsalar çoğu zaman bulunduğunuz ülkede lisanslı değildir."],["Kendi ülkenizin kurallarını, platformun kullanım koşullarını ve çekim limitlerini önceden okuyun. Varlıklarınızı uzun süre böyle bir platformda bırakmamak ve DEX kullanırken ",["akıllı sözleşme","smart-contract"]," riskini bilmek temel önlemlerdir."]],"example":["Bir merkezi borsanın KYC'siz hesaplara günlük 1 ",["BTC","bitcoin"],"'ye eşdeğer çekim limiti tanıdığını varsayalım. Hesabınızda 0,8 BTC var ve bunu çekmek istiyorsunuz; limit içinde olduğunuz için sorun yaşamazsınız. Ancak işlemleriniz büyüyüp bakiyeniz 3 BTC'ye çıktığında, tamamını çekmek için en az 3 gün beklersiniz. Bu arada platform kurallarını değiştirip KYC zorunlu hâle getirirse 3 BTC kimlik doğrulaması bitene kadar hesabınızda kalır."],"mistakes":["KYC'siz borsanın hiçbir zaman kimlik istemeyeceğine güvenmek.","Büyük bakiyeleri uzun süre lisanssız bir platformda tutmak.","DEX'te sahte token sözleşmelerini ve onay (approve) risklerini göz ardı etmek."],"faq":[{"q":"KYC'siz borsa yasal mı?","a":"Bu ülkeye göre değişir. Birçok ülkede kripto hizmet sağlayıcılarının KYC uygulaması zorunludur; lisanssız platform kullanmanın sonuçlarını kendi ülkenizin mevzuatına göre değerlendirmeniz gerekir."},{"q":"DEX'ler neden kimlik istemez?","a":"DEX'ler bir şirketin hesabı yerine akıllı sözleşmeler üzerinden çalışır ve varlıklarınızı saklamaz. Ancak arayüzü işleten şirketler bazı bölgeleri engelleyebilir."}],"title":"KYC'siz borsa nedir? Kimliksiz kripto alım satımı","description":"KYC'siz borsa nedir, DEX ile merkezi no-KYC platform farkı nedir, çekim limitleri ve fon dondurma riski nasıl işler, öğrenin.","related":[["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC nasıl yapılır ve kimlik kime verilmelidir?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"tr","term":"Fiat giriş kanalı (fiat on-ramp)","aka":["fiat on-ramp","on-ramp","TL yatırma","fiat yatırma"],"short":"Fiat giriş kanalı (on-ramp), Türk lirası, dolar veya euro gibi geleneksel parayı kripto varlığa çevirmenizi sağlayan yol ya da hizmettir; banka havalesi, kartla alım ve P2P bunun örnekleridir.","body":[["Kripto dünyasına ilk adım genellikle bir on-ramp'tir. En yaygın yollar şunlardır: borsaya banka havalesi veya EFT ile TL yatırmak, kredi ya da banka kartıyla doğrudan kripto almak, ",["P2P","p2p-trading"]," pazarında başka bir kullanıcıdan banka transferiyle ",["USDT","usdt"]," almak ve üçüncü taraf ödeme sağlayıcıları."],"Her yolun maliyeti ve hızı farklıdır. Banka transferi genellikle en ucuz yoldur ama mesai saatlerine bağlı olabilir. Kartla alım hızlıdır ama ücret ve kur farkı daha yüksek olabilir. P2P'de fiyat satıcıya göre değişir ve karşı taraf riskini yönetmek gerekir.","Off-ramp ise tersidir: kriptoyu tekrar TL'ye çevirip bankaya çekmek. Bir borsa seçerken yalnızca alım tarafına değil, paranızı geri çekme yollarına ve limitlerine de bakmanız önemlidir."],"example":"10.000 TL ile USDT almak istediğinizi ve kurun 1 USDT = 40 TL olduğunu varsayalım. Banka havalesiyle ücretsiz yatırıp spot piyasada yüzde 0,1 ücretle alırsanız yaklaşık 249,75 USDT alırsınız. Kartla alım yüzde 2 maliyet getirirse yaklaşık 245 USDT elde edersiniz. P2P'de satıcı 40,40 TL fiyat veriyorsa yaklaşık 247,5 USDT alırsınız. Aynı 10.000 TL farklı yollarla 4 USDT'den fazla fark yaratır.","mistakes":["Yalnızca hıza bakıp kartla alımın toplam maliyetini hesaplamamak.","Banka havalesinde borsanın istediği açıklama kodunu yazmayı unutmak.","Para yatırmadan önce aynı yoldan çekim yapılabildiğini kontrol etmemek."],"faq":[{"q":"Borsaya TL nasıl yatırılır?","a":"TL hesabı sunan borsalarda genellikle kendi adınıza kayıtlı bankadan havale veya EFT ile yatırma yapılır. Borsanın gösterdiği IBAN ve açıklama bilgilerini aynen kullanmanız gerekir."},{"q":"En ucuz on-ramp hangisi?","a":"Çoğu durumda banka transferiyle yatırıp spot piyasada almak en ucuz yoldur. Yine de ücretler borsaya ve döneme göre değiştiği için toplam maliyeti karşılaştırmak gerekir."}],"title":"Fiat on-ramp nedir? TL'den kriptoya giriş yolları","description":"Fiat on-ramp nedir, havale, kart ve P2P ile TL'den kriptoya geçişte maliyetler nasıl değişir, hesaplamalı örnekle öğrenin.","related":[["p2p-trading","P2P alım satım (C2C)","P2P alım satım, kullanıcıların borsanın aracılık ettiği bir pazarda, kripto varlığı birbirlerinden banka transferi gibi ödeme yöntemleriyle doğrudan aldığı veya sattığı işlem türüdür."],["kyc","KYC (müşterini tanı)","KYC (Know Your Customer, müşterini tanı), kripto borsalarının ve finansal kuruluşların kullanıcının kimliğini, adresini ve bazen gelir kaynağını doğruladığı zorunlu kimlik doğrulama sürecidir."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"İlk para yatırma: Para nereden gelir ve nereye gider?"},"coin":null,"tool":null,"cta":true}});
